--create database, masterkey, credential setup,data source & file format creation


--Create Data base
create database bronze;
create database silver;
create database gold;
GO

--- create database scoped credentail(managed identity)

use bronze;
GO
create master key encryption by PASSWORD = 'Adhira_06rajalakshmiIlango';
Go
create database scoped credential synapse_credential
        with identity = 'managed identity';
GO

Use silver;
GO

create master key encryption by PASSWORD = 'Adhira_06rajalakshmiIlango';
Go

create database scoped credential synapse_credential
with identity = 'managed identity';
GO

Use gold;
GO

create master key encryption by PASSWORD = 'Adhira_06rajalakshmiIlango';
Go

create database scoped credential synapse_credential
with identity = 'managed identity';
GO
SELECT name, credential_identity
FROM sys.database_scoped_credentials;
GO

--create external data sources
use bronze;
GO

create external data source bronze_source
with (
    Location = 'https://synapseadlsrav1.dfs.core.windows.net/newyorkrawdata',
    credential = synapse_credential
);
Go

use silver;
GO

create external data source silver_source
with (
    Location = 'https://synapseadlsrav1.dfs.core.windows.net/newyorkrawdata',
    credential = synapse_credential
);
Go

use gold;
GO
DROP EXTERNAL DATA SOURCE gold_source;
create external data source gold_source
with (
    Location = 'https://synapseadlsrav1.dfs.core.windows.net/newyorkrawdata',
    credential = synapse_credential
);
Go

select * from sys.external_data_sources;

--create file formats

use bronze;
GO
--Csv file format
create external file format csv_format
    with(
        format_type = DELIMITEDTEXT,
        format_options(
            field_terminator = ',' ,
            first_row = 2,
            encoding = 'UTF8',
            use_type_default = false
        )
    );
    GO
use bronze;
go
IF EXISTS (SELECT 1 FROM sys.external_file_formats WHERE name = 'parqet_format')
    DROP EXTERNAL FILE FORMAT parqet_format;

CREATE EXTERNAL FILE FORMAT parquet_format
WITH (
    FORMAT_TYPE      = PARQUET,
    DATA_COMPRESSION = 'org.apache.hadoop.io.compress.SnappyCodec'
);
GO

--delta format

create external file format delta_format
with(
    format_type = DELTA
);
Go

-- verify setup
select name from sys.databases
where name in('bronze','silver','gold');

select * from sys.external_file_formats;
